:root {
  --color-bg: #ffffff;
  --color-bg-alt: #f3f1ec;
  --color-bg-alt-2: #e8e4db;
  --color-text: #2b2b27;
  --color-text-muted: #55534c;
  --color-brand-dark: #1f3a3d;
  --color-brand-darker: #152a2c;
  --color-dark-bg: #16282a;
  --color-accent-on-dark: #e8d9b5;
  --color-border: #d8d3c6;
  --font-body: Georgia, "Times New Roman", serif;
  --font-mono: "Courier New", monospace;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 3.5rem;
  --radius: 4px;
  --max-width: 75rem;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3, h4 {
  font-family: var(--font-body);
  color: var(--color-brand-darker);
  line-height: 1.25;
  margin-top: 0;
}

h1 { font-size: clamp(1.8rem, 4vw, 2.75rem); }
h2 { font-size: clamp(1.4rem, 3vw, 2rem); }
h3 { font-size: 1.2rem; }

p { margin-top: 0; }

a { color: var(--color-brand-dark); text-decoration: underline; }
a:hover { color: var(--color-brand-darker); }
a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 3px solid var(--color-brand-dark);
  outline-offset: 2px;
}

img { max-width: 100%; height: auto; display: block; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* Header */
header {
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
  padding-top: var(--space-sm);
  padding-bottom: var(--space-sm);
}

.logo {
  font-family: var(--font-mono);
  font-weight: 700;
  text-transform: lowercase;
  letter-spacing: 0.05em;
  font-size: clamp(1.2rem, 4vw, 1.5rem);
  color: var(--color-brand-darker);
  text-decoration: none;
  white-space: nowrap;
}

.logo span {
  color: var(--color-brand-dark);
}

.logo:hover { color: var(--color-brand-dark); }

nav[aria-label="Main"] ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin: 0;
  padding: 0;
}

nav[aria-label="Main"] a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 600;
  padding: 0.5rem 0.25rem;
  display: inline-block;
}

nav[aria-label="Main"] a:hover,
nav[aria-label="Main"] a:focus-visible {
  color: var(--color-brand-dark);
}

/* Footer */
footer {
  background: var(--color-dark-bg);
  color: var(--color-accent-on-dark);
  margin-top: var(--space-lg);
}

.footer-inner {
  padding-top: var(--space-md);
  padding-bottom: var(--space-md);
  text-align: center;
}

.footer-logo {
  font-weight: 700;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-xs);
  color: var(--color-accent-on-dark);
}

footer address { font-style: normal; margin-bottom: var(--space-xs); }

footer a { color: var(--color-accent-on-dark); }
footer a:hover { color: #ffffff; }

.copyright { font-size: 0.875rem; opacity: 0.9; margin-bottom: 0; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  border: 2px solid transparent;
  font-size: 1rem;
}

.btn-primary {
  background: var(--color-brand-dark);
  color: #ffffff;
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: var(--color-brand-darker);
  color: #ffffff;
}

.btn-secondary {
  background: transparent;
  color: var(--color-brand-dark);
  border-color: var(--color-brand-dark);
}
.btn-secondary:hover, .btn-secondary:focus-visible {
  background: var(--color-brand-dark);
  color: #ffffff;
}

/* Cards */
.card {
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--space-sm);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.card img {
  border-radius: var(--radius);
  margin-bottom: var(--space-xs);
}

.card h3 { margin-bottom: 0.25rem; }

/* Grid helper */
.grid {
  display: grid;
  gap: var(--space-md);
  grid-template-columns: 1fr;
}

.grid-2 { grid-template-columns: 1fr; }
.grid-3 { grid-template-columns: 1fr; }

/* Sections */
section {
  padding: var(--space-lg) 0;
}

.section-alt {
  background: var(--color-bg-alt);
}

.section-dark {
  background: var(--color-dark-bg);
  color: var(--color-accent-on-dark);
}

.section-dark h2, .section-dark h3 { color: var(--color-accent-on-dark); }

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  max-width: 40rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-weight: 700;
  color: var(--color-brand-darker);
}

input, textarea, select {
  min-height: 44px;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-family: inherit;
  font-size: 1rem;
  background: var(--color-bg);
  color: var(--color-text);
}

textarea {
  min-height: 8rem;
  resize: vertical;
}

input:focus, textarea:focus, select:focus {
  border-color: var(--color-brand-dark);
}

/* Utility */
.text-center { text-align: center; }
.muted { color: var(--color-text-muted); }

/* Mobile breakpoint */
@media (max-width: 600px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
  }
  nav[aria-label="Main"] ul {
    width: 100%;
    justify-content: flex-start;
  }
  section {
    padding: var(--space-md) 0;
  }
  .container {
    padding: 0 1rem;
  }
}

/* Desktop breakpoint */
@media (min-width: 601px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .header-inner { flex-wrap: nowrap; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { animation: none !important; transition: none !important; }
}

pages.css:
.index-hero { padding-top: var(--space-lg); padding-bottom: var(--space-lg); background: var(--color-bg-alt); }
.index-hero-inner { max-width: 48rem; }
.index-hero-lede { font-size: 1.15rem; color: var(--color-text-muted); margin-bottom: var(--space-md); }
.index-hero-actions { display: flex; flex-wrap: wrap; gap: var(--space-sm); }

.index-highlights-grid { margin-top: var(--space-md); }

.index-philosophy-inner { display: grid; gap: var(--space-md); align-items: center; grid-template-columns: 1fr; }
.index-philosophy-text p { margin-bottom: var(--space-sm); color: var(--color-text-muted); }
.index-philosophy-image { border-radius: var(--radius); width: 100%; }

.index-cta-lede { max-width: 36rem; margin: 0 auto var(--space-md); color: var(--color-accent-on-dark); }
.index-cta-btn { min-height: 48px; }

@media (min-width: 601px) {
  .index-philosophy-inner { grid-template-columns: 1.1fr 1fr; }
}

@media (max-width: 600px) {
  .index-hero-actions { flex-direction: column; }
  .index-hero-actions .btn { width: 100%; }
}

.projects-lead {
  max-width: 48rem;
  font-size: 1.1rem;
  color: var(--color-text-muted);
}

.projects-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  list-style: none;
  margin: var(--space-sm) 0 0;
  padding: 0;
}

.projects-tags li {
  background: var(--color-bg-alt-2);
  color: var(--color-brand-darker);
  border: 1px solid var(--color-border);
  border-radius: 999px;
  padding: 0.35rem 0.9rem;
  font-size: 0.9rem;
  font-weight: 700;
}

.projects-grid .card img {
  aspect-ratio: 4 / 3;
  object-fit: cover;
  width: 100%;
}

.projects-featured {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  align-items: start;
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
}

.projects-featured-img {
  width: 100%;
  height: auto;
  object-fit: cover;
  aspect-ratio: 16 / 9;
  margin: 0;
  border-radius: 0;
}

.projects-featured-body {
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.projects-featured-body .btn {
  align-self: flex-start;
  margin-top: var(--space-xs);
}

@media (min-width: 601px) {
  .projects-featured {
    grid-template-columns: 1.1fr 1fr;
  }
  .projects-featured-img {
    height: 100%;
    aspect-ratio: auto;
  }
}

@media (max-width: 600px) {
  .projects-tags li {
    font-size: 0.85rem;
    padding: 0.3rem 0.7rem;
  }
}

.team-culture-grid { align-items: stretch; }

.team-member img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
}

.team-role {
  font-weight: 700;
  color: var(--color-brand-dark);
  margin: 0;
}

#join-us .btn-primary {
  margin-top: var(--space-sm);
}

@media (max-width: 600px) {
  .team-members-grid {
    gap: var(--space-sm);
  }
}

@media (min-width: 601px) {
  .team-member {
    text-align: left;
  }
}

.services-intro-text {
  max-width: 48rem;
  font-size: 1.1rem;
  color: var(--color-text-muted);
}

.services-price {
  font-weight: 700;
  color: var(--color-brand-dark);
  margin-top: auto;
}

.services-note {
  margin-top: var(--space-md);
  max-width: 48rem;
}

.services-process-list {
  list-style: none;
  margin: var(--space-md) 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.services-process-step {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}

.services-step-number {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background: var(--color-brand-dark);
  color: #ffffff;
  font-weight: 700;
  font-size: 1.25rem;
}

.services-process-step h3 {
  margin-bottom: 0.25rem;
}

.services-cta {
  margin-top: var(--space-lg);
}

@media (max-width: 600px) {
  .services-process-step {
    gap: 0.75rem;
  }
  .services-step-number {
    width: 2.5rem;
    height: 2.5rem;
    font-size: 1.1rem;
  }
}

@media (min-width: 601px) {
  .services-process-list {
    max-width: 44rem;
  }
}

.contact-intro { padding-bottom: var(--space-md); }

.contact-checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
}

.contact-checkbox-row input[type="checkbox"] {
  min-height: auto;
  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.2rem;
  flex-shrink: 0;
}

.contact-checkbox-row label {
  font-weight: 400;
  color: var(--color-text);
}

.contact-details-grid {
  align-items: start;
}

.contact-card h3 {
  margin-top: var(--space-sm);
}

.contact-card h3:first-child {
  margin-top: 0;
}

.contact-address {
  font-style: normal;
}

.contact-hours {
  width: 100%;
  border-collapse: collapse;
  margin-top: var(--space-xs);
}

.contact-hours caption {
  text-align: left;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
}

.contact-hours th,
.contact-hours td {
  text-align: left;
  padding: 0.5rem 0.25rem;
  border-bottom: 1px solid var(--color-border);
}

.contact-hours th {
  font-weight: 700;
  color: var(--color-brand-darker);
}

@media (max-width: 600px) {
  .contact-hours th,
  .contact-hours td {
    font-size: 0.95rem;
  }
}

@media (min-width: 601px) {
  .contact-details-section .container {
    padding-top: var(--space-xs);
  }
}

