  font-size: 0.9rem;
  font-weight: 700;
}

.projects-grid .card img {
  aspect-ratio: 4 / 3;
  object-fit: cover;
  width: 100%;
}

.projects-featured {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  align-items: start;
  background: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
}

.projects-featured-img {
  width: 100%;
  height: auto;
  object-fit: cover;
  aspect-ratio: 16 / 9;
  margin: 0;
  border-radius: 0;
}

.projects-featured-body {
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.projects-featured-body .btn {
  align-self: flex-start;
  margin-top: var(--space-xs);
}

@media (min-width: 601px) {
  .projects-featured {
    grid-template-columns: 1.1fr 1fr;
  }
  .projects-featured-img {
    height: 100%;
    aspect-ratio: auto;
  }
}

@media (max-width: 600px) {
  .projects-tags li {
    font-size: 0.85rem;
    padding: 0.3rem 0.7rem;
  }
}

.team-culture-grid { align-items: stretch; }

.team-member img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
}

.team-role {
  font-weight: 700;
  color: var(--color-brand-dark);
  margin: 0;
}

#join-us .btn-primary {
  margin-top: var(--space-sm);
}

@media (max-width: 600px) {
  .team-members-grid {
    gap: var(--space-sm);
  }
}

@media (min-width: 601px) {
  .team-member {
    text-align: left;
  }
}

.services-intro-text {
  max-width: 48rem;
  font-size: 1.1rem;
  color: var(--color-text-muted);
}

.services-price {
  font-weight: 700;
  color: var(--color-brand-dark);
  margin-top: auto;
}

.services-note {
  margin-top: var(--space-md);
  max-width: 48rem;
}

.services-process-list {
  list-style: none;
  margin: var(--space-md) 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.services-process-step {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}

.services-step-number {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background: var(--color-brand-dark);
  color: #ffffff;
  font-weight: 700;
  font-size: 1.25rem;
}

.services-process-step h3 {
  margin-bottom: 0.25rem;
}

.services-cta {
  margin-top: var(--space-lg);
}

@media (max-width: 600px) {
  .services-process-step {
    gap: 0.75rem;
  }
  .services-step-number {
    width: 2.5rem;
    height: 2.5rem;
    font-size: 1.1rem;
  }
}

@media (min-width: 601px) {
  .services-process-list {
    max-width: 44rem;
  }
}

.contact-intro { padding-bottom: var(--space-md); }

.contact-checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
}

.contact-checkbox-row input[type="checkbox"] {
  min-height: auto;
  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.2rem;
  flex-shrink: 0;
}

.contact-checkbox-row label {
  font-weight: 400;
  color: var(--color-text);
}

.contact-details-grid {
  align-items: start;
}

.contact-card h3 {
  margin-top: var(--space-sm);
}

.contact-card h3:first-child {
  margin-top: 0;
}

.contact-address {
  font-style: normal;
}

.contact-hours {
  width: 100%;
  border-collapse: collapse;
  margin-top: var(--space-xs);
}

.contact-hours caption {
  text-align: left;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
}

.contact-hours th,
.contact-hours td {
  text-align: left;
  padding: 0.5rem 0.25rem;
  border-bottom: 1px solid var(--color-border);
}

.contact-hours th {
  font-weight: 700;
  color: var(--color-brand-darker);
}

@media (max-width: 600px) {
  .contact-hours th,
  .contact-hours td {
    font-size: 0.95rem;
  }
}

@media (min-width: 601px) {
  .contact-details-section .container {
    padding-top: var(--space-xs);
  }
}
